using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Errors;
using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;
using FiveSmartFarmCreators.Ichu.Platform.Shared.Application.Model;
using FiveSmartFarmCreators.Ichu.Platform.Shared.Domain.Model.Aggregates.Internal;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Aggregates;

/// <summary>
///     A reading captured by a collar and relayed by an Edge Gateway. Its identity is the device together with the reading identifier generated by the firmware, which never changes across retries.
/// </summary>
public sealed class TelemetryReading : AggregateRoot
{
    // Readings older than this are presented with their age and never as current.
    public static readonly TimeSpan StalenessLimit = TimeSpan.FromHours(24);

    // Entity Framework Core materializes readings without running the factory.
    private TelemetryReading()
    {
    }

    public TelemetryReadingId Id { get; private set; }

    public Guid ReadingId { get; private set; }

    public Guid DeviceId { get; private set; }

    public Guid GatewayId { get; private set; }

    public Guid RanchId { get; private set; }

    public Guid? CattleId { get; private set; }

    public DateTimeOffset RecordedAt { get; private set; }

    public DateTimeOffset ReceivedAt { get; private set; }

    public Measurement BodyTemperature { get; private set; } = Measurement.Absent();

    public Measurement ActivityIndex { get; private set; } = Measurement.Absent();

    public Measurement HeartRate { get; private set; } = Measurement.Absent();

    public Measurement MethaneIndex { get; private set; } = Measurement.Absent();

    public Measurement RuminationMinutes { get; private set; } = Measurement.Absent();

    public Measurement BatteryPercent { get; private set; } = Measurement.Absent();

    public PositionMeasurement Position { get; private set; } = PositionMeasurement.Absent();

    public static Result<TelemetryReading> Create(
        Guid readingId,
        Guid deviceId,
        DateTimeOffset recordedAt,
        Measurement bodyTemperature,
        Measurement activityIndex,
        Measurement heartRate,
        Measurement methaneIndex,
        Measurement ruminationMinutes,
        Measurement batteryPercent,
        PositionMeasurement position,
        Guid gatewayId,
        Guid ranchId,
        Guid? cattleId,
        DateTimeOffset receivedAt)
    {
        if (readingId == Guid.Empty || deviceId == Guid.Empty || gatewayId == Guid.Empty || ranchId == Guid.Empty)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.ReadingIdentifiersRequired);
        }

        if (cattleId == Guid.Empty)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.AttributedAnimalRequired);
        }

        if (activityIndex.Value < 0)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.ActivityIndexNegative);
        }

        if (heartRate.Value is < 30 or > 200)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.HeartRateOutOfRange);
        }

        if (methaneIndex.Value is < 0 or > 100)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.MethaneIndexOutOfRange);
        }

        if (ruminationMinutes.Value < 0)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.RuminationMinutesNegative);
        }

        if (batteryPercent.Value is < 0 or > 100)
        {
            return Result<TelemetryReading>.Failure(OperationsMonitoringErrors.BatteryLevelOutOfRange);
        }

        return Result<TelemetryReading>.Success(new TelemetryReading
        {
            Id = new TelemetryReadingId(Guid.NewGuid()),
            ReadingId = readingId,
            DeviceId = deviceId,
            RecordedAt = MonitoringTime.Normalize(recordedAt),
            BodyTemperature = bodyTemperature,
            ActivityIndex = activityIndex,
            HeartRate = heartRate,
            MethaneIndex = methaneIndex,
            RuminationMinutes = ruminationMinutes,
            BatteryPercent = batteryPercent,
            Position = position,
            GatewayId = gatewayId,
            RanchId = ranchId,
            CattleId = cattleId,
            ReceivedAt = MonitoringTime.Normalize(receivedAt)
        });
    }

    public bool IsStale(DateTimeOffset now) => now - RecordedAt > StalenessLimit;

    public Measurement MeasurementOf(MonitoredMetric metric) => metric switch
    {
        MonitoredMetric.BodyTemperature => BodyTemperature,
        MonitoredMetric.ActivityIndex => ActivityIndex,
        MonitoredMetric.HeartRate => HeartRate,
        MonitoredMetric.MethaneIndex => MethaneIndex,
        // Every monitored metric is mapped above, so an unknown value is a programming error.
        _ => throw new ArgumentOutOfRangeException(nameof(metric), metric, null)
    };

    // The relaying gateway and the reception time are excluded because they do not describe what the device captured.
    public bool HasSameCaptureAs(TelemetryReading other) =>
        ReadingId == other.ReadingId &&
        DeviceId == other.DeviceId &&
        RecordedAt == other.RecordedAt &&
        BodyTemperature == other.BodyTemperature &&
        ActivityIndex == other.ActivityIndex &&
        HeartRate == other.HeartRate &&
        MethaneIndex == other.MethaneIndex &&
        RuminationMinutes == other.RuminationMinutes &&
        BatteryPercent == other.BatteryPercent &&
        Position == other.Position;
}
